import{_ as t,o as s,c as a,a3 as l}from"./chunks/framework.CRbjHCyB.js";const b=JSON.parse('{"title":"代码操作","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"代码操作 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/features/code-action"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/features/code-action"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/features/code-action"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/features/code-action"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/features/code-action"}]]},"headers":[],"relativePath":"zh/clice/features/code-action.md","filePath":"zh/clice/features/code-action.md","lastUpdated":1788607538000}'),c={name:"zh/clice/features/code-action.md"};function i(r,e,o,n,d,h){return s(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="代码操作" tabindex="-1">代码操作 <a class="header-anchor" href="#代码操作" aria-label="Permalink to &quot;代码操作&quot;">​</a></h1><p>clice 尚未声明支持 <code>textDocument/codeAction</code>。目前，直接发送的请求会进入存根处理器并返回空列表。本页记录计划支持的范围。</p><h2 id="快速修复" tabindex="-1">快速修复 <a class="header-anchor" href="#快速修复" aria-label="Permalink to &quot;快速修复&quot;">​</a></h2><p>由 clang / clang-tidy 诊断附带的 <code>FixItHint</code> 派生而来的操作。</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 将编译器的 <code>FixItHint</code> 作为快速修复应用</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 应用 clang-tidy 修复建议</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>source.fixAll</code> — 批量应用文件中的所有可用修复（<a href="https://github.com/clangd/clangd/issues/1446" target="_blank" rel="noreferrer">clangd#1446</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 一次性修复同类诊断的所有实例（<a href="https://github.com/clangd/clangd/issues/830" target="_blank" rel="noreferrer">clangd#830</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 应用会修改主文件以外内容的修复（<a href="https://github.com/clangd/clangd/issues/1747" target="_blank" rel="noreferrer">clangd#1747</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 遵循客户端的代码操作能力（<code>isPreferred</code>、resolve 支持）（<a href="https://github.com/clangd/clangd/issues/573" target="_blank" rel="noreferrer">clangd#573</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 可选择格式化代码操作生成的编辑（<a href="https://github.com/clangd/clangd/issues/2476" target="_blank" rel="noreferrer">clangd#2476</a>）</li></ul><h2 id="包含指令操作" tabindex="-1">包含指令操作 <a class="header-anchor" href="#包含指令操作" aria-label="Permalink to &quot;包含指令操作&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 为未解析的符号添加缺失的 <code>#include</code>（<a href="https://github.com/clangd/clangd/issues/1017" target="_blank" rel="noreferrer">clangd#1017</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 插入包含指令时使用项目相对路径，而非绝对路径（<a href="https://github.com/clangd/clangd/issues/2010" target="_blank" rel="noreferrer">clangd#2010</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 包含指令样式可配置——双引号或尖括号（<a href="https://github.com/clangd/clangd/issues/1367" target="_blank" rel="noreferrer">clangd#1367</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 移除未使用的 <code>#include</code>（include-cleaner）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 遵循 IWYU pragma（<code>export</code>、<code>keep</code>、<code>private</code>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 建议使用 <code>using</code> 声明，作为对未解析符号进行限定的替代方案（<a href="https://github.com/clangd/clangd/issues/976" target="_blank" rel="noreferrer">clangd#976</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> C 文件：建议 <code>&lt;stdlib.h&gt;</code> 而非 <code>&lt;cstdlib&gt;</code>（<a href="https://github.com/clangd/clangd/issues/2246" target="_blank" rel="noreferrer">clangd#2246</a>）</li></ul><h2 id="重构" tabindex="-1">重构 <a class="header-anchor" href="#重构" aria-label="Permalink to &quot;重构&quot;">​</a></h2><p>由光标或选区驱动的重构操作。</p><h3 id="提取" tabindex="-1">提取 <a class="header-anchor" href="#提取" aria-label="Permalink to &quot;提取&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 提取变量（<a href="https://github.com/clangd/clangd/issues/446" target="_blank" rel="noreferrer">clangd#446</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 提取变量时应替换该表达式的所有出现位置（<a href="https://github.com/clangd/clangd/issues/924" target="_blank" rel="noreferrer">clangd#924</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 从宏实参中提取变量（<a href="https://github.com/clangd/clangd/issues/1197" target="_blank" rel="noreferrer">clangd#1197</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 提取函数或方法（<a href="https://github.com/clangd/clangd/issues/698" target="_blank" rel="noreferrer">clangd#698</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 提取函数应保留占位返回类型（<code>auto</code>）（<a href="https://github.com/clangd/clangd/issues/653" target="_blank" rel="noreferrer">clangd#653</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 提取函数不得引入脱糖后的类型（<a href="https://github.com/clangd/clangd/issues/1496" target="_blank" rel="noreferrer">clangd#1496</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 提取函数须处理在外层作用域定义的类型（<a href="https://github.com/clangd/clangd/issues/1710" target="_blank" rel="noreferrer">clangd#1710</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 在 C 文件中提取函数（<a href="https://github.com/clangd/clangd/issues/1810" target="_blank" rel="noreferrer">clangd#1810</a>）</li></ul><h3 id="内联-展开" tabindex="-1">内联 / 展开 <a class="header-anchor" href="#内联-展开" aria-label="Permalink to &quot;内联 / 展开&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 内联变量或函数</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 展开 <code>auto</code> 或推导类型</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 将宏展开一层（<a href="https://github.com/clangd/clangd/issues/820" target="_blank" rel="noreferrer">clangd#820</a>）</li></ul><h3 id="移动-定义" tabindex="-1">移动 / 定义 <a class="header-anchor" href="#移动-定义" aria-label="Permalink to &quot;移动 / 定义&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 在类外定义方法（将方法体移出类）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 内联定义方法（将方法体移入声明中）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 根据声明生成缺失的方法定义（<a href="https://github.com/clangd/clangd/issues/445" target="_blank" rel="noreferrer">clangd#445</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 根据类外定义生成缺失的声明（<a href="https://github.com/clangd/clangd/issues/2454" target="_blank" rel="noreferrer">clangd#2454</a>、<a href="https://github.com/clangd/clangd/issues/730" target="_blank" rel="noreferrer">clangd#730</a>）</li></ul><h3 id="转换" tabindex="-1">转换 <a class="header-anchor" href="#转换" aria-label="Permalink to &quot;转换&quot;">​</a></h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 添加 <code>using</code> 声明（<a href="https://github.com/clangd/clangd/issues/73" target="_blank" rel="noreferrer">clangd#73</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 通过就地限定名称来替换 <code>using namespace</code>（<a href="https://github.com/clangd/clangd/issues/1067" target="_blank" rel="noreferrer">clangd#1067</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 移除不必要的类型限定符（<a href="https://github.com/clangd/clangd/issues/1619" target="_blank" rel="noreferrer">clangd#1619</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 交换 <code>if</code>/<code>else</code> 分支（<a href="https://github.com/clangd/clangd/issues/466" target="_blank" rel="noreferrer">clangd#466</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 补全 <code>switch</code> 分支（<a href="https://github.com/clangd/clangd/issues/807" target="_blank" rel="noreferrer">clangd#807</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 转换为原始字符串字面量</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 根据使用处创建声明（<a href="https://github.com/clangd/clangd/issues/467" target="_blank" rel="noreferrer">clangd#467</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 移除函数/方法（<a href="https://github.com/clangd/clangd/issues/2580" target="_blank" rel="noreferrer">clangd#2580</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 修改函数参数并更新调用点（<a href="https://github.com/clangd/clangd/issues/460" target="_blank" rel="noreferrer">clangd#460</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 修复声明与定义的签名不匹配问题（<a href="https://github.com/clangd/clangd/issues/77" target="_blank" rel="noreferrer">clangd#77</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 为基类的纯虚方法生成存根（<a href="https://github.com/clangd/clangd/issues/1037" target="_blank" rel="noreferrer">clangd#1037</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 交换二元运算符的操作数</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 将无作用域枚举转换为有作用域枚举</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 生成逐成员构造函数</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 声明隐式的拷贝/移动特殊成员函数</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 重命名符号（作为代码操作）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Include-cleaner：批量修复未使用或缺失的 include</li></ul>',17)])])}const g=t(c,[["render",i]]);export{b as __pageData,g as default};
